use crate::jobs::error::{JobError, JobResult};
use crate::jobs::types::{Job, JobStatus, JobType};
use chrono::{DateTime, Utc};
use serde_json::Value as JsonValue;
use sqlx::{Pool, Postgres, QueryBuilder};
use uuid::Uuid;

/// Parsed filter parameters for listing jobs.
/// Shared contract between the handler (which parses query strings) and the repository.
#[derive(Debug, Clone, Default)]
pub struct JobListFilters {
    pub status: Vec<JobStatus>,
    pub job_type: Vec<JobType>,
    pub created_after: Option<DateTime<Utc>>,
    pub created_before: Option<DateTime<Utc>>,
}

/// Repository for job CRUD operations and job queue claiming
#[derive(Debug, Clone)]
pub struct JobRepository {
    pool: Pool<Postgres>,
}

impl JobRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Get reference to the connection pool
    pub fn pool(&self) -> &Pool<Postgres> {
        &self.pool
    }

    /// Create a new job in pending status
    pub async fn create_job(
        &self,
        job_type: JobType,
        payload: JsonValue,
    ) -> JobResult<Job> {
        let job = Job::new(job_type, payload);

        sqlx::query_as::<_, Job>(
            r#"
            INSERT INTO jobs (id, job_type, status, payload, created_at, updated_at)
            VALUES ($1, $2, $3, $4, $5, $6)
            RETURNING *
            "#
        )
        .bind(job.id)
        .bind(&job.job_type)
        .bind(&job.status)
        .bind(&job.payload)
        .bind(job.created_at)
        .bind(job.updated_at)
        .fetch_one(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Get job by ID
    pub async fn get_job(&self, id: Uuid
    ) -> JobResult<Option<Job>> {
        sqlx::query_as::<_, Job>(
            "SELECT * FROM jobs WHERE id = $1"
        )
        .bind(id)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Claim next pending job using FOR UPDATE SKIP LOCKED (race-free)
    /// Returns the claimed job or None if no jobs available
    pub async fn claim_next_job(
        &self,
        worker_id: &str,
    ) -> JobResult<Option<Job>> {
        let now = Utc::now();

        sqlx::query_as::<_, Job>(
            r#"
            UPDATE jobs 
            SET status = 'in_process', 
                started_at = $1, 
                updated_at = $1,
                worker_id = $2
            WHERE id = (
                SELECT id FROM jobs 
                WHERE status = 'pending' 
                ORDER BY created_at 
                FOR UPDATE SKIP LOCKED
                LIMIT 1
            )
            RETURNING *
            "#
        )
        .bind(now)
        .bind(worker_id)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// Update job status with validation
    pub async fn update_job_status(
        &self,
        id: Uuid,
        new_status: JobStatus,
        result: Option<JsonValue>,
        error: Option<JsonValue>,
    ) -> JobResult<Job> {
        // Get current job to validate transition
        let current = self.get_job(id).await?;
        let job = current.ok_or_else(|| JobError::NotFound(id.to_string()))?;

        let current_status = job.status_enum()
            .ok_or_else(|| JobError::Other(format!("Invalid status: {}", job.status)))?;

        if !current_status.can_transition_to(new_status) {
            return Err(JobError::InvalidStatusTransition(
                current_status.to_string(),
                new_status.to_string(),
            ));
        }

        let now = Utc::now();

        sqlx::query_as::<_, Job>(
            r#"
            UPDATE jobs 
            SET status = $1, 
                updated_at = $2,
                completed_at = CASE WHEN $1 IN ('complete', 'failed') THEN $2 ELSE completed_at END,
                result = COALESCE($3, result),
                error = COALESCE($4, error)
            WHERE id = $5
            RETURNING *
            "#
        )
        .bind(new_status.as_ref())
        .bind(now)
        .bind(result)
        .bind(error)
        .bind(id)
        .fetch_one(&self.pool)
        .await
        .map_err(JobError::from)
    }

    /// List jobs with dynamic filtering and pagination
    #[allow(unused_assignments)]
    pub async fn list_jobs(
        &self,
        filters: JobListFilters,
        limit: i64,
        offset: i64,
    ) -> JobResult<Vec<Job>> {
        let mut query = QueryBuilder::new("SELECT * FROM jobs");
        let mut has_where = false;

        if !filters.status.is_empty() {
            query.push(" WHERE status IN (");
            let mut separated = query.separated(", ");
            for s in &filters.status {
                separated.push_bind(s.as_ref());
            }
            query.push(")");
            has_where = true;
        }

        if !filters.job_type.is_empty() {
            if has_where {
                query.push(" AND job_type IN (");
            } else {
                query.push(" WHERE job_type IN (");
                has_where = true;
            }
            let mut separated = query.separated(", ");
            for jt in &filters.job_type {
                separated.push_bind(jt.as_ref());
            }
            query.push(")");
        }

        if let Some(after) = filters.created_after {
            if has_where {
                query.push(" AND created_at >= ");
            } else {
                query.push(" WHERE created_at >= ");
                has_where = true;
            }
            query.push_bind(after);
        }

        if let Some(before) = filters.created_before {
            if has_where {
                query.push(" AND created_at <= ");
            } else {
                query.push(" WHERE created_at <= ");
                has_where = true;
            }
            query.push_bind(before);
        }

        query.push(" ORDER BY created_at DESC LIMIT ");
        query.push_bind(limit);
        query.push(" OFFSET ");
        query.push_bind(offset);

        query.build_query_as::<Job>()
            .fetch_all(&self.pool)
            .await
            .map_err(JobError::from)
    }

    /// Count jobs with dynamic filtering
    #[allow(unused_assignments)]
    pub async fn count_jobs(&self, filters: JobListFilters) -> JobResult<i64> {
        let mut query = QueryBuilder::new("SELECT COUNT(*) FROM jobs");
        let mut has_where = false;

        if !filters.status.is_empty() {
            query.push(" WHERE status IN (");
            let mut separated = query.separated(", ");
            for s in &filters.status {
                separated.push_bind(s.as_ref());
            }
            query.push(")");
            has_where = true;
        }

        if !filters.job_type.is_empty() {
            if has_where {
                query.push(" AND job_type IN (");
            } else {
                query.push(" WHERE job_type IN (");
                has_where = true;
            }
            let mut separated = query.separated(", ");
            for jt in &filters.job_type {
                separated.push_bind(jt.as_ref());
            }
            query.push(")");
        }

        if let Some(after) = filters.created_after {
            if has_where {
                query.push(" AND created_at >= ");
            } else {
                query.push(" WHERE created_at >= ");
                has_where = true;
            }
            query.push_bind(after);
        }

        if let Some(before) = filters.created_before {
            if has_where {
                query.push(" AND created_at <= ");
            } else {
                query.push(" WHERE created_at <= ");
                has_where = true;
            }
            query.push_bind(before);
        }

        let count: (i64,) = query.build_query_as()
            .fetch_one(&self.pool)
            .await
            .map_err(JobError::from)?;

        Ok(count.0)
    }
}

/// Repository for tracking loaded date ranges
#[derive(Debug, Clone)]
pub struct LoadedDaysRepository {
    pool: Pool<Postgres>,
}

impl LoadedDaysRepository {
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Mark a date as loaded with coverage information
    pub async fn mark_day_loaded(
        &self,
        date: chrono::NaiveDate,
        coverage_minutes: i16,
        job_id: Option<Uuid>,
    ) -> JobResult<()> {
        sqlx::query(
            r#"
            INSERT INTO loaded_days (date, coverage_minutes, loaded_at, job_id)
            VALUES ($1, $2, NOW(), $3)
            ON CONFLICT (date) DO UPDATE SET
                coverage_minutes = EXCLUDED.coverage_minutes,
                loaded_at = EXCLUDED.loaded_at,
                job_id = EXCLUDED.job_id
            "#
        )
        .bind(date)
        .bind(coverage_minutes)
        .bind(job_id)
        .execute(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(())
    }

    /// Check if a date is already loaded
    pub async fn is_day_loaded(
        &self,
        date: chrono::NaiveDate,
    ) -> JobResult<bool> {
        let row: Option<(i64,)> = sqlx::query_as(
            "SELECT 1 FROM loaded_days WHERE date = $1 LIMIT 1"
        )
        .bind(date)
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(row.is_some())
    }

    /// Get dates in a range that are NOT loaded
    pub async fn get_missing_dates(
        &self,
        start: chrono::NaiveDate,
        days: i64,
    ) -> JobResult<Vec<chrono::NaiveDate>> {
        // Generate series of dates and find which aren't in loaded_days
        let rows: Vec<(chrono::NaiveDate,)> = sqlx::query_as(
            r#"
            SELECT gs::date as date
            FROM generate_series($1::date, $1::date + ($2 || ' days')::interval, '1 day'::interval) gs
            WHERE gs::date NOT IN (
                SELECT date FROM loaded_days 
                WHERE date BETWEEN $1 AND $1 + ($2 || ' days')::interval
            )
            ORDER BY gs::date
            "#
        )
        .bind(start)
        .bind(days)
        .fetch_all(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(rows.into_iter().map(|r| r.0).collect())
    }

    /// Get loaded date range summary
    pub async fn get_loaded_range_summary(
        &self,
    ) -> JobResult<Option<(chrono::NaiveDate, chrono::NaiveDate, i64)>> {
        let row: Option<(chrono::NaiveDate, chrono::NaiveDate, i64)> = sqlx::query_as(
            "SELECT MIN(date), MAX(date), COUNT(*) FROM loaded_days"
        )
        .fetch_optional(&self.pool)
        .await
        .map_err(JobError::from)?;

        Ok(row)
    }
}

//! Job API route handlers
//!
//! Provides endpoints for:
//! - POST /api/v1/load - Create and execute load jobs (sync or async)
//! - GET /api/v1/jobs/:id - Get job status and details

#![cfg(feature = "db")]

use axum::extract::{Path, Query, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;
use uuid::Uuid;

use std::str::FromStr;

use crate::jobs::repository::{JobListFilters, JobRepository};
use crate::jobs::types::{Job, JobStatus, JobType};
use crate::server::state::AppState;

/// Request to create a load job
#[derive(Debug, Deserialize)]
pub struct LoadRequest {
    /// Start date in YYYY-MM-DD format
    pub start_date: String,
    /// Number of days to load (1-365)
    pub days: i64,
    /// If true, execute synchronously and wait for completion
    /// If false or omitted, execute asynchronously and return job-id immediately
    #[serde(default)]
    pub sync: Option<bool>,
}

/// Response for successful sync load execution
#[derive(Debug, Serialize)]
pub struct LoadSyncResponse {
    pub job_id: Uuid,
    pub status: String,
    pub result: Option<JsonValue>,
}

/// Response for async load submission
#[derive(Debug, Serialize)]
pub struct LoadAsyncResponse {
    pub job_id: Uuid,
    pub status: String,
    pub poll_url: String,
}

/// Response for job status query
#[derive(Debug, Serialize)]
pub struct JobResponse {
    pub job_id: Uuid,
    pub job_type: String,
    pub status: String,
    pub payload: Option<JsonValue>,
    pub result: Option<JsonValue>,
    pub error: Option<JobErrorResponse>,
    pub created_at: String,
    pub updated_at: String,
    pub started_at: Option<String>,
    pub completed_at: Option<String>,
}

/// Error details for failed jobs
#[derive(Debug, Serialize)]
pub struct JobErrorResponse {
    pub code: String,
    pub message: String,
}

/// Error response body
#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    pub error: String,
    pub message: String,
}

/// Request parameters for listing jobs
#[derive(Debug, Deserialize)]
pub struct ListJobsRequest {
    /// Filter by status — comma-separated for multi-value (e.g. "complete,failed")
    pub status: Option<String>,
    /// Filter by job type — comma-separated for multi-value (e.g. "load,query")
    pub job_type: Option<String>,
    /// Filter jobs created on or after this timestamp (RFC3339 or YYYY-MM-DD)
    pub created_after: Option<String>,
    /// Filter jobs created on or before this timestamp (RFC3339 or YYYY-MM-DD)
    pub created_before: Option<String>,
    /// Maximum number of jobs to return (default: 20, max: 100)
    #[serde(default = "default_limit")]
    pub limit: i64,
    /// Offset for pagination (default: 0)
    #[serde(default = "default_offset")]
    pub offset: i64,
}

fn default_limit() -> i64 { 20 }
fn default_offset() -> i64 { 0 }

/// Parse a date string as a UTC DateTime.
/// Tries RFC3339 first, then falls back to YYYY-MM-DD (interpreted as start-of-day UTC).
fn parse_date_param(s: &str) -> Result<DateTime<Utc>, String> {
    // Try RFC3339 first (e.g. "2025-01-15T10:30:00Z")
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Ok(dt.to_utc());
    }
    // Fall back to YYYY-MM-DD (start of day UTC)
    if let Ok(date) = NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        return date
            .and_hms_opt(0, 0, 0)
            .map(|nd| DateTime::<Utc>::from_naive_utc_and_offset(nd, Utc))
            .ok_or_else(|| format!("Invalid date: '{}'", s));
    }
    Err(format!(
        "Invalid date format: '{}'. Expected RFC3339 (2025-01-15T10:30:00Z) or YYYY-MM-DD",
        s
    ))
}

/// Parse a comma-separated string into a Vec<T> using FromStr.
/// Returns the first error encountered, if any.
fn parse_comma_separated<T: FromStr>(input: &str, label: &str) -> Result<Vec<T>, String> {
    let mut results = Vec::new();
    for part in input.split(',') {
        let trimmed = part.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<T>() {
            Ok(v) => results.push(v),
            Err(_) => {
                return Err(format!(
                    "Invalid {} value: '{}'. Example valid values: {}",
                    label,
                    trimmed,
                    // Show the label contextually — callers provide meaningful labels
                    input
                ));
            }
        }
    }
    Ok(results)
}

/// Response for job listing
#[derive(Debug, Serialize)]
pub struct ListJobsResponse {
    pub jobs: Vec<JobResponse>,
    pub total: i64,
    pub limit: i64,
    pub offset: i64,
}

/// POST /api/v1/load - Create and execute a load job
///
/// In sync mode (sync=true): Blocks until completion, returns full job with result
/// In async mode (sync=false or omitted): Returns immediately with job-id for polling
pub async fn load_handler(
    State(state): State<AppState>,
    Json(request): Json<LoadRequest>,
) -> impl IntoResponse {
    // Validate days parameter (must be 1-365)
    if request.days < 1 || request.days > 365 {
        let error = ErrorResponse {
            error: "invalid_days".to_string(),
            message: format!("Days must be between 1 and 365, got {}", request.days),
        };
        return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error))).into_response();
    }

    // Validate date format (YYYY-MM-DD)
    if NaiveDate::parse_from_str(&request.start_date, "%Y-%m-%d").is_err() {
        let error = ErrorResponse {
            error: "invalid_date".to_string(),
            message: format!(
                "Invalid date format: '{}', expected YYYY-MM-DD",
                request.start_date
            ),
        };
        return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error))).into_response();
    }

    // Build payload JSON
    let payload = serde_json::json!({
        "start_date": request.start_date,
        "days": request.days,
    });

    let sync_mode = request.sync.unwrap_or(false);

    if sync_mode {
        // Synchronous execution: block until completion
        match state.executor().execute_sync(JobType::Load, payload).await {
            Ok(job) => {
                let response = LoadSyncResponse {
                    job_id: job.id,
                    status: job.status,
                    result: job.result,
                };
                (StatusCode::OK, Json(serde_json::json!(response))).into_response()
            }
            Err(e) => {
                tracing::error!("Sync load job failed: {}", e);
                let error = ErrorResponse {
                    error: "execution_failed".to_string(),
                    message: format!("{}", e),
                };
                (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
            }
        }
    } else {
        // Asynchronous execution: return job-id immediately
        match state.executor().execute_async(JobType::Load, payload).await {
            Ok(job_id) => {
                let response = LoadAsyncResponse {
                    job_id,
                    status: "pending".to_string(),
                    poll_url: format!("/api/v1/jobs/{}", job_id),
                };
                (StatusCode::ACCEPTED, Json(serde_json::json!(response))).into_response()
            }
            Err(e) => {
                tracing::error!("Async load job submission failed: {}", e);
                let error = ErrorResponse {
                    error: "submission_failed".to_string(),
                    message: format!("{}", e),
                };
                (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
            }
        }
    }
}

/// GET /api/v1/jobs/:id - Get job details and status
///
/// Returns full job information including:
/// - Job metadata (id, type, status, timestamps)
/// - Payload (input parameters)
/// - Result (output data, if complete)
/// - Error (error details, if failed)
pub async fn get_job_handler(
    State(state): State<AppState>,
    Path(job_id): Path<Uuid>,
) -> impl IntoResponse {
    let repository = JobRepository::new(state.get_pool());

    match repository.get_job(job_id).await {
        Ok(Some(job)) => {
            let response = build_job_response(job);
            (StatusCode::OK, Json(serde_json::json!(response))).into_response()
        }
        Ok(None) => {
            let error = ErrorResponse {
                error: "not_found".to_string(),
                message: format!("Job {} not found", job_id),
            };
            (StatusCode::NOT_FOUND, Json(serde_json::json!(error))).into_response()
        }
        Err(e) => {
            tracing::error!("Failed to get job {}: {}", job_id, e);
            let error = ErrorResponse {
                error: "query_failed".to_string(),
                message: format!("{}", e),
            };
            (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
        }
    }
}

/// GET /api/v1/jobs - List recent jobs with pagination and filtering
///
/// Query parameters:
/// - status: Comma-separated status filter (e.g. "complete,failed")
/// - job_type: Comma-separated job type filter (e.g. "load,query")
/// - created_after: Filter by created_at >= timestamp (RFC3339 or YYYY-MM-DD)
/// - created_before: Filter by created_at <= timestamp (RFC3339 or YYYY-MM-DD)
/// - limit: Max jobs to return (default: 20, max: 100)
/// - offset: Pagination offset (default: 0)
pub async fn list_jobs_handler(
    State(state): State<AppState>,
    Query(params): Query<ListJobsRequest>,
) -> impl IntoResponse {
    let repository = JobRepository::new(state.get_pool());

    // Validate and cap limit
    let limit = params.limit.max(1).min(100);
    let offset = params.offset.max(0);

    // Parse comma-separated status filter
    let statuses: Vec<JobStatus> = match params.status.as_deref() {
        Some(s) => {
            let parsed = parse_comma_separated::<JobStatus>(s, "status");
            match parsed {
                Ok(v) => v,
                Err(msg) => {
                    let error = ErrorResponse {
                        error: "invalid_status".to_string(),
                        message: format!(
                            "{}. Valid values: pending, in_process, complete, failed",
                            msg
                        ),
                    };
                    return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error)))
                        .into_response();
                }
            }
        }
        None => Vec::new(),
    };

    // Parse comma-separated job_type filter
    let job_types: Vec<JobType> = match params.job_type.as_deref() {
        Some(s) => {
            let parsed = parse_comma_separated::<JobType>(s, "job_type");
            match parsed {
                Ok(v) => v,
                Err(msg) => {
                    let error = ErrorResponse {
                        error: "invalid_job_type".to_string(),
                        message: format!(
                            "{}. Valid values: load, query",
                            msg
                        ),
                    };
                    return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error)))
                        .into_response();
                }
            }
        }
        None => Vec::new(),
    };

    // Parse created_after date
    let created_after = match params.created_after.as_deref() {
        Some(s) => {
            match parse_date_param(s) {
                Ok(dt) => Some(dt),
                Err(msg) => {
                    let error = ErrorResponse {
                        error: "invalid_date".to_string(),
                        message: format!("Invalid created_after: {}", msg),
                    };
                    return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error)))
                        .into_response();
                }
            }
        }
        None => None,
    };

    // Parse created_before date
    let created_before = match params.created_before.as_deref() {
        Some(s) => {
            match parse_date_param(s) {
                Ok(dt) => Some(dt),
                Err(msg) => {
                    let error = ErrorResponse {
                        error: "invalid_date".to_string(),
                        message: format!("Invalid created_before: {}", msg),
                    };
                    return (StatusCode::BAD_REQUEST, Json(serde_json::json!(error)))
                        .into_response();
                }
            }
        }
        None => None,
    };

    let filters = JobListFilters {
        status: statuses,
        job_type: job_types,
        created_after,
        created_before,
    };

    // Get total count for pagination
    let total_result = repository.count_jobs(filters.clone()).await;

    match total_result {
        Ok(total) => {
            match repository.list_jobs(filters, limit, offset).await {
                Ok(jobs) => {
                    let responses: Vec<JobResponse> = jobs
                        .into_iter()
                        .map(build_job_response)
                        .collect();

                    let response = ListJobsResponse {
                        jobs: responses,
                        total,
                        limit,
                        offset,
                    };

                    (StatusCode::OK, Json(serde_json::json!(response))).into_response()
                }
                Err(e) => {
                    tracing::error!("Failed to list jobs: {}", e);
                    let error = ErrorResponse {
                        error: "query_failed".to_string(),
                        message: format!("Failed to retrieve jobs: {}", e),
                    };
                    (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
                }
            }
        }
        Err(e) => {
            tracing::error!("Failed to count jobs: {}", e);
            let error = ErrorResponse {
                error: "query_failed".to_string(),
                message: format!("Failed to count jobs: {}", e),
            };
            (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!(error))).into_response()
        }
    }
}

/// Build a JobResponse from a Job entity
fn build_job_response(job: Job) -> JobResponse {
    let error_response = job.error.map(|err| {
        // Try to extract code and message from error JSON
        let code = err
            .get("code")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown_error")
            .to_string();
        let message = err
            .get("message")
            .and_then(|v| v.as_str())
            .unwrap_or("An unknown error occurred")
            .to_string();
        JobErrorResponse { code, message }
    });

    JobResponse {
        job_id: job.id,
        job_type: job.job_type,
        status: job.status,
        payload: job.payload,
        result: job.result,
        error: error_response,
        created_at: job.created_at.to_rfc3339(),
        updated_at: job.updated_at.to_rfc3339(),
        started_at: job.started_at.map(|t| t.to_rfc3339()),
        completed_at: job.completed_at.map(|t| t.to_rfc3339()),
    }
}

